diff --git a/src/ui/prompts.rs b/src/ui/prompts.rs
index 2141ce1..551bcbe 100644
--- a/src/ui/prompts.rs
+++ b/src/ui/prompts.rs
@@ -1,5 +1,7 @@
 //! Interactive prompts.

+use std::io;
+
 use console::{measure_text_width, style, Key, Style, Term};
 use dialoguer::theme::ColorfulTheme;
 use dialoguer::{Confirm, Input, MultiSelect, Select};
@@ -8,9 +10,27 @@ use crate::error::{BivvyError, Result};

 use super::{Prompt, PromptOption, PromptResult, PromptType};

-/// Convert dialoguer errors to BivvyError.
+/// Check if an IO error represents EOF (e.g. from Ctrl+D).
+fn is_eof(e: &io::Error) -> bool {
+    e.kind() == io::ErrorKind::UnexpectedEof
+}
+
+/// Convert an EOF IO error into a user-friendly interrupted error.
+fn handle_eof(e: io::Error) -> BivvyError {
+    if is_eof(&e) {
+        BivvyError::Io(io::Error::new(
+            io::ErrorKind::Interrupted,
+            "Interrupted (EOF)",
+        ))
+    } else {
+        BivvyError::Io(e)
+    }
+}
+
+/// Convert dialoguer errors to BivvyError, handling EOF gracefully.
 fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
-    BivvyError::Io(e.into())
+    let io_err: io::Error = e.into();
+    handle_eof(io_err)
 }

 /// Dialoguer theme without the default yellow `?` prefix.
@@ -160,8 +180,15 @@ fn prompt_yes_no(prompt: &Prompt, options: &[PromptOption], term: &Term) -> Resu
         }
         term.flush().map_err(BivvyError::Io)?;

-        // Read key
-        let key = term.read_key().map_err(BivvyError::Io)?;
+        // Read key, restoring terminal state on EOF/error
+        let key = match term.read_key() {
+            Ok(key) => key,
+            Err(e) => {
+                term.clear_last_lines(options.len()).ok();
+                term.show_cursor().ok();
+                return Err(handle_eof(e));
+            }
+        };

         let chosen = match key {
             Key::Char('y') | Key::Char('Y') => options.iter().position(|o| o.value == "yes"),
@@ -382,4 +409,25 @@ mod tests {
         // Verify the theme object can be used (smoke test)
         drop(theme);
     }
+
+    #[test]
+    fn eof_error_is_detected() {
+        let eof = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
+        assert!(is_eof(&eof));
+
+        let other = std::io::Error::other("something else");
+        assert!(!is_eof(&other));
+    }
+
+    #[test]
+    fn eof_converted_to_interrupted_error() {
+        let eof = std::io::Error::new(std::io::ErrorKind::UnexpectedEof, "EOF");
+        let err = handle_eof(eof);
+        let msg = err.to_string();
+        assert!(
+            msg.contains("nterrupt"),
+            "expected 'Interrupted' in: {}",
+            msg
+        );
+    }
 }

